# Find the unmatched completed runs and inspect their last events
import json

events = []
with open('.yoyo/state/events.jsonl') as f:
    for line in f:
        line = line.strip()
        if line:
            try:
                events.append(json.loads(line))
            except:
                pass

run_completed = set()
run_started = set()
for e in events:
    kind = e.get('kind','')
    run_id = e.get('run_id','')
    if kind == 'RunCompleted':
        run_completed.add(run_id)
    elif kind == 'RunStarted':
        run_started.add(run_id)

unmatched = run_completed - run_started
print(f'Total events: {len(events)}')
print(f'RunCompleted: {len(run_completed)}, RunStarted: {len(run_started)}')
print(f'Unmatched completed: {unmatched}')
print(f'Unmatched started: {run_started - run_completed}')

# Show all RunCompleted events for unmatched runs
for rid in unmatched:
    for e in events:
        if e.get('run_id') == rid and e.get('kind') == 'RunCompleted':
            print(f'\\nUnmatched RunCompleted:')
            print(json.dumps(e, indent=2))
" 2>&1

